sys_script.script:
(function executeRule(current, previous) {
    var auditGr = new GlideRecord('x_1919740_dayone_0_readiness_audit');
    auditGr.initialize();
    auditGr.setValue('plan', current.getUniqueValue());

    var details = [];

    if (current.getValue('readiness_status') != previous.getValue('readiness_status')) {
        auditGr.setValue('event_type', 'status_changed');
        auditGr.setValue('previous_status', previous.getValue('readiness_status'));
        auditGr.setValue('new_status', current.getValue('readiness_status'));
        details.push('Status changed from ' + previous.getValue('readiness_status') + ' to ' + current.getValue('readiness_status'));
    }

    if (current.getValue('readiness_score') != previous.getValue('readiness_score')) {
        if (!auditGr.getValue('event_type')) {
            auditGr.setValue('event_type', 'score_recalculated');
        }
        details.push('Score changed from ' + previous.getValue('readiness_score') + ' to ' + current.getValue('readiness_score'));
    }

    auditGr.setValue('score', current.getValue('readiness_score'));
    auditGr.setValue('performed_by', gs.getUserID());
    auditGr.setValue('details', details.join('. '));
    auditGr.insert();
})(current, previous);
